import app from 'flarum/admin/app';
let sortable = null;

/**
 * Core's lazily loaded SortableJS chunk, shared rather than bundling another copy.
 */
export function loadSortable() {
  return sortable ||= flarum.reg.asyncModuleImport('flarum/admin/utils/loadSortable').then(module => module.default);
}

/**
 * Makes a list's `[data-id]` children draggable by `handle`; `onsort` gets the ids in their new order.
 *
 * SortableJS moves DOM nodes behind Mithril's back, so callers must re-key the list after `onsort`.
 */
export function makeSortable(element, handle, onsort) {
  loadSortable().then(Sortable => {
    Sortable.create(element, {
      handle,
      animation: 150,
      delay: 50,
      delayOnTouchOnly: true,
      ghostClass: 'sortable-placeholder',
      onSort: () => onsort(Array.from(element.children).map(child => child.dataset.id))
    });
  });
}
export function saveOrder(url, ids) {
  return app.request({
    method: 'POST',
    url: app.forum.attribute('apiUrl') + url,
    body: {
      sort: ids
    }
  });
}
flarum.reg.add('fof-mason', 'admin/utils/sortable', { loadSortable: loadSortable,makeSortable: makeSortable,saveOrder: saveOrder, });