import Model from 'flarum/common/Model';
import computed from 'flarum/common/utils/computed';
export default class Field extends Model {
  name() {
    return Model.attribute('name').call(this);
  }
  description() {
    return Model.attribute('description').call(this);
  }
  min_answers_count() {
    return Model.attribute('min_answers_count').call(this);
  }
  max_answers_count() {
    return Model.attribute('max_answers_count').call(this);
  }
  show_when_empty() {
    return Model.attribute('show_when_empty').call(this);
  }
  user_values_allowed() {
    return Model.attribute('user_values_allowed').call(this);
  }
  validation() {
    return Model.attribute('validation').call(this);
  }
  icon() {
    return Model.attribute('icon').call(this);
  }
  sort() {
    return Model.attribute('sort').call(this);
  }
  allAnswers() {
    return Model.hasMany('allAnswers').call(this);
  }
  suggestedAnswers() {
    return Model.hasMany('suggestedAnswers').call(this);
  }
  required() {
    return computed('min_answers_count', min_answers_count => min_answers_count > 0).call(this);
  }
  multiple() {
    return computed('max_answers_count', max_answers_count => max_answers_count > 1).call(this);
  }
}
flarum.reg.add('fof-mason', 'common/models/Field', Field);