import Model from 'flarum/common/Model';
export default class Answer extends Model {
  content() {
    return Model.attribute('content').call(this);
  }
  is_suggested() {
    return Model.attribute('is_suggested').call(this);
  }
  sort() {
    return Model.attribute('sort').call(this);
  }
  field() {
    return Model.hasOne('field').call(this);
  }
}
flarum.reg.add('fof-mason', 'common/models/Answer', Answer);