import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import FieldList from './FieldList';

/**
 * Core's extension page (registered settings + permissions) with the field manager on top.
 */
export default class MasonPage extends ExtensionPage {
  sections(vnode) {
    const items = super.sections(vnode);
    items.add('fields', m("div", {
      className: "ExtensionPage-settings MasonPage-fields"
    }, m("div", {
      className: "container"
    }, m("h3", {
      className: "ExtensionPage-subHeader"
    }, app.translator.trans('fof-mason.admin.titles.fields')), m(FieldList, null))), 10);
    return items;
  }
}
flarum.reg.add('fof-mason', 'admin/components/MasonPage', MasonPage);